"""Post-hoc reporting only: never changes frozen models, prompts or thresholds."""
import json,statistics,hashlib
from collections import Counter
from pathlib import Path
import numpy as np
from sklearn.metrics import accuracy_score,f1_score,confusion_matrix,precision_recall_fscore_support
OUT=Path('data/experiments/iso-hybrid-v1')

def read(name):return json.loads((OUT/name).read_text())
def lines(name):return [json.loads(x) for x in (OUT/name).read_text().splitlines()]
def label(value,key):
    if key=='votable':return 'UNCERTAIN' if value=='UNKNOWN' else value
    if isinstance(value,bool):return 'YES' if value else 'NO'
    return 'UNKNOWN' if value is None else value

def metrics(rows):
    fields={}
    for key in ['votable','share_blocking','poa_required','other_restriction','deadline_status']:
        use=[r for r in rows if key in r['expected']];y=[label(r['expected'][key],key) for r in use];p=[label(r['observed'].get(key),key) for r in use]
        labels=['YES','NO','UNCERTAIN'] if key=='votable' else ['OPEN','PASSED','UNKNOWN'] if key=='deadline_status' else ['YES','NO','UNKNOWN']
        precision,recall,f1,support=precision_recall_fscore_support(y,p,labels=labels,zero_division=0)
        fields[key]={'n':len(y),'correct':sum(a==b for a,b in zip(y,p)),'accuracy':float(accuracy_score(y,p)),'macro_f1_fixed_labels':float(f1_score(y,p,labels=labels,average='macro',zero_division=0)),'weighted_f1':float(f1_score(y,p,labels=labels,average='weighted',zero_division=0)),'labels':labels,'confusion_matrix':confusion_matrix(y,p,labels=labels).tolist(),'per_class':{k:{'precision':float(precision[i]),'recall':float(recall[i]),'f1':float(f1[i]),'support':int(support[i])} for i,k in enumerate(labels)}}
    return {'cases':len(rows),'passed':sum(r['passed'] for r in rows),'fields':fields,'note':'Partial challenge assertions, not fully annotated exact-match events. Fixed class vocabularies shared across models, including unsupported classes with F1=0.'}

def report():
    parser=read('parser-verification.json');public=read('public-parser-summary.json');routing=read('public-routing-summary.json')
    historical=Path('data/experiments/supplied-synthetic-v1')
    allrows={'legacy_base':json.loads((historical/'base-challenge.json').read_text())['examples'],'legacy_fine':json.loads((historical/'fine-tuned-challenge.json').read_text())['examples'],'hybrid_base':lines('base-challenge.jsonl'),'hybrid_fine':lines('fine-challenge.jsonl')}
    comparison={k:metrics(v) for k,v in allrows.items()}
    (OUT/'comparison-fixed-labels.json').write_text(json.dumps(comparison,indent=2))
    pairs={n:read(n+'-minimal-pairs.json') for n in ['base','fine']}
    pm={}
    for n,r in pairs.items():
        pm[n]={}
        for key in ['share_blocking','poa_required','registration_required','beneficial_owner_disclosure_required','split_voting_restricted','securities_lending_recall_required','other_voting_restriction']:
            rows=[x for x in r['rows'] if key in x['expected']];y=[x['expected'][key] for x in rows];p=[x['result']['predicates'][key]['value'] for x in rows];labels=['YES','NO','UNKNOWN']
            pm[n][key]={'n':len(rows),'correct':sum(a==b for a,b in zip(y,p)),'accuracy':float(accuracy_score(y,p)),'macro_f1_fixed_labels':float(f1_score(y,p,labels=labels,average='macro',zero_division=0)),'labels':labels,'confusion_matrix':confusion_matrix(y,p,labels=labels).tolist()}
    (OUT/'minimal-pair-metrics.json').write_text(json.dumps(pm,indent=2))
    coverage={}
    for n in ['base','fine']:
        rows=lines(n+'-validation.jsonl');points=[]
        for t in [.5,.7,.8,.9,.95,.98]:
            selected=[]
            for r in rows:
                a=r['result']['predicates'];confidence=min((v['confidence'] if v['confidence'] is not None else 0 for v in a.values()),default=0)
                if confidence>=t:selected.append(all(label(a[k]['value'],k)==r['expected'][k] for k in r['expected']))
            points.append({'threshold':t,'n':len(selected),'coverage':len(selected)/len(rows),'exact_three_predicate_accuracy':sum(selected)/len(selected) if selected else None,'errors':len(selected)-sum(selected)})
        coverage[n]=points
    (OUT/'synthetic-validation-coverage.json').write_text(json.dumps({'scope':'Known leaky AI-synthetic validation; only three reference-labelled predicates; NOT safe operational automation','models':coverage,'automation_enabled':False},indent=2))
    errors='# Hybrid Laya: every authored challenge failure\n\nExact frozen outputs; no expectations were changed. Scores are native passage distributions, not document-status probabilities. Candidate evidence is source-exact, not a verified causal explanation.\n\n'
    for name in ['hybrid_base','hybrid_fine']:
        rows=allrows[name];bad=[r for r in rows if not r['passed']]
        errors+=f'## {name}: {len(bad)} / 57 failures\n\n'
        for r in bad:
            errors+=f"### {r['id']}\n\nSource:\n\n```text\n{r['text']}\n```\n\nExpected:\n\n```json\n{json.dumps(r['expected'],indent=2)}\n```\n\nObserved:\n\n```json\n{json.dumps({k:r['observed'].get(k) for k in r['expected']},indent=2)}\n```\n\nFailed assertions: {', '.join(k for k,v in r['checks'].items() if not v)}. Tags: {', '.join(r['tags'])}. These are descriptive patterns, not invented causal explanations.\n\n"
            sem=r['result']['semantic_analysis']
            errors+='All available selected-passage scores, confidence, margin, conflict and candidate evidence:\n\n```json\n'+json.dumps(sem.get('predicates',{}),indent=2,ensure_ascii=False)+'\n```\n\n'
            errors+='Every passage distribution is retained in `'+('base' if name=='hybrid_base' else 'fine')+'-challenge.jsonl`. Deadline comparison:\n\n```json\n'+json.dumps(r['result']['deadline'],indent=2)+'\n```\n\n'
    Path('data/reports/ISO15022_HYBRID_ERRORS.md').write_text(errors)
    m='# ISO15022 hybrid evaluation\n\nMeasured 16 October 2026. **Quality gate not met; automation disabled. No customer accuracy claim.**\n\n'
    m+='## 1. Public sources\n\nSee [source research](ISO15022_PROXY_RESEARCH.md) and `data/iso15022_corpus/research_sources.json`: public ISO dictionary, Clearstream/LuxCSD service specifications and official example, Euroclear, SIX SIS, DTCC, Euronext and ISO/SMPG context. Direct SMPG document access was blocked; third-party mirrors were excluded. No private MyStandards material was used. Current Clearstream meeting flows use ISO20022 for instructions/status/results; MT564 coexistence is notification/cancellation only. Generic ISO15022 capability is not current sender acceptance.\n\n'
    m+=f"## 2–3. Genuine examples and generated coverage\n\n{parser['official_excerpts']} short official disclosure-message excerpt; **zero public production messages**. Other public documents contain examples not copied into this corpus. {parser['standards_derived_partial']} generated partial-message fixtures, including 25 explicit notification/narrative/replacement/cancellation chains; {parser['malformed_mutations']} mutations. Every item has source type, URL, organisation, retrieval date, message type, notes and checksums in `sources.jsonl`. These fixtures are excluded from semantic training. They are not a substitute for production data.\n\n"
    m+='## 4–5. Parser support\n\nMT564, MT565, MT567 and MT568 have experimental subset field routing. MT566 can be retained as opaque confirmation history, not a decoded voting confirmation. Supported: nested/repeated 16R/16S, 20C SEME/CORP/COAF/PREV/RELA, 23G function, GENL 22F CAEV/CAMV, USECU 35B ISIN/description, scoped CAON/CAOP and option indicators, 98A/C/E dates with qualifier/precision/offset, coded 98B dates, selected narrative qualifiers, and preserved processing status. Unknown tags/qualifiers/DSS and unsupported date alternatives remain lossless and visible. This is **not complete mandatory-field, network or sender-profile validation**; VALID_ISO15022 is deliberately withheld.\n\n'
    m+=f"## 6–7. Exact parser and robustness checks\n\n{parser['exact_assertions_passed']} / {parser['exact_assertions_total']} reference-value assertions passed across generated partial fixtures and the official excerpt. {parser['field_source_spans_checked']} field spans checked. No crashes across all {parser['corpus_items']} items, including 500 mutations. Property tests exercise 525 generated cases per suite run: arbitrary Unicode, CR/LF/CRLF, envelopes, narrative text, valid calendar dates and lossless segment coverage. This tests bounded inputs, not all possible malformed data, full grammar compliance or production accuracy. See `artifacts/hybrid-app-tests-final.log`.\n\n"
    m+=f"## 8. Existing public excerpts\n\nAll {public['records']} processed, zero failed rows, {public['elapsed_seconds']:.3f}s detector/parser time. Counts: {json.dumps(public['counts'])}. Zero recognised tags, zero usable ISO structure. Nine short/unrecognised records are retained for review. Thus the existing corpus primarily tests unstructured semantics, not ISO parsing. Raw source files are unchanged.\n\n"
    m+=f"## 9–12. Deterministic facts, model routing and escalation\n\nThe public routing audit defines nine decision slots per record: vote, seven restrictions and deadline ({routing['total_decision_fact_slots']} slots). Deterministic non-unknown outputs: {routing['deterministic_nonunknown_fact_outputs']} ({routing['deterministic_output_fraction']:.1%}). Planned Laya slots: {routing['planned_laya_predicate_slots']} ({routing['planned_laya_slot_fraction']:.2%}); these are **planned routes**, not completed inference or verified fact resolution. Narrow Laya was not run over all 7,683 rows in this phase. Actual LLM escalations: zero; fallback is disabled and no external dependency exists. Human-review policy: {routing['human_review_cases']} / {routing['records']} (100%). Full-corpus ML percentages and verified fact accuracy are unmeasured. Parser/rule assertions, semantic scores and final customer decisions remain separate in the GUI.\n\n"
    m+='## 13. Narrow predicate learning and evaluation\n\nA new official-SDK Laya fine-tune used exactly the supplied 300 TRAIN rows and 100 VALIDATION rows, seed 42, four epochs, full encoder, soft CE, option shuffle, no internal calibration split; validation-only temperature fitting. Checkpoint `data/models/narrow-v1`; manifests/config/hashes/losses under `data/experiments/narrow-v1`. All 300 rows train three compatible targets (900 question-items): voting opportunity, share blocking and POA. These are **AI-authored synthetic labels, not expert reviews**. The supplied splits have known duplicate leakage, disclosed in the previous study. No new independent frozen test was available. The previously scored 100-row test was not reused. The original blind-test artifacts and all frozen historical files remain intact. Existing 57 challenge cases and ISO fixtures never train the model.\n\nNo compatible labels exist for registration, owner disclosure, split voting, lending recall or the new residual restriction. Their outputs are transfer-only experiments, not domain-trained or validated predicates. Old “other restriction” labels overlap the expanded predicates and were not silently relabelled as residual truth. New review labels are still needed.\n\nKnown synthetic validation, same 100 rows (three labelled predicates only):\n\n| Predicate | Narrow base | Narrow fine-tuned |\n|---|---:|---:|\n'
    for key in ['votable','share_blocking','poa_required']:
        b=read('base-validation-summary.json')[key];f=read('fine-validation-summary.json')[key];m+=f"| {key} | {b['accuracy']:.1%} | {f['accuracy']:.1%} |\n"
    m+='\nThese are diagnostics after sentence aggregation, not independent test accuracy. Native SDK outputs and per-field confusion matrices are persisted.\n\nNew authored minimal-pair diagnostics, never training:\n\n| Predicate | n | Base correct | Fine correct |\n|---|---:|---:|---:|\n'
    for key in pm['base']:
        b=pm['base'][key];f=pm['fine'][key];m+=f"| {key} | {b['n']} | {b['correct']} | {f['correct']} |\n"
    m+=f"\nOverall: base {pairs['base']['passed']}/17; fine {pairs['fine']['passed']}/17. Tiny authored samples do not establish predicate accuracy. The fine-tune regresses on these diagnostics. Source-exact candidate evidence and all native passage scores remain available.\n\n"
    m+='## 14. Old versus new on the unchanged 57-case challenge\n\n| Architecture | Passed | Failed |\n|---|---:|---:|\n'
    for k,d in comparison.items():m+=f"| {k} | {d['passed']} | {57-d['passed']} |\n"
    m+='\nAll 57 compatible cases were evaluated using their original partial expected assertions; no expected answers changed. No ISO structure is present. Whole-text fine-tuning beats this narrow pipeline; base hybrid is worse than legacy base. Narrow fine-tuning improves over narrow base but does not outperform the best preserved legacy model. The new pipeline changes semantic framing, chunking and conservative rule policy together; this is not an isolated parser ablation.\n\nChallenge field agreement (denominators differ because expected labels are partial):\n\n| Field | n | Narrow base correct | Narrow fine correct | Base macro F1 | Fine macro F1 |\n|---|---:|---:|---:|---:|---:|\n'
    for key in comparison['hybrid_base']['fields']:
        b=comparison['hybrid_base']['fields'][key];f=comparison['hybrid_fine']['fields'][key];m+=f"| {key} | {b['n']} | {b['correct']} | {f['correct']} | {b['macro_f1_fixed_labels']:.3f} | {f['macro_f1_fixed_labels']:.3f} |\n"
    m+='\n`comparison-fixed-labels.json` uses the same three-class vocabulary for both models, unlike the raw exploratory summaries whose observed-label union can differ. Deadline agreement (13/14 for both) is deterministic and **must not be reported as Laya semantic accuracy**. Full confusion matrices and per-class precision/recall/support are in the JSON.\n\n'
    m+='## 15. Failure modes and auditability\n\n[Every hybrid challenge failure](ISO15022_HYBRID_ERRORS.md) includes text, expected/observed assertions, scores, margin/confidence, evidence and deadline calculations. Raw JSONL retains every sentence distribution. Remaining problems include voting/non-voting confusion, missed or contradictory restrictions, negation and supersession. In the narrow fine-tune POA and untrained residual restrictions regress. Opposing confident sentence predictions abstain; this prevents washing away a positive but also treats absent requirements in unrelated passages as conflicting negatives. Sentence segmentation currently treats physical narrative lines as passage boundaries; wrapped ISO text can lose context. Neither sentence scores nor exact quotations guarantee valid supporting evidence. Superseded semantic narrative is not reliably resolved.\n\nThe persistent event ledger retains sender+CORP identity, SEME/source hashes, source messages, current and superseded fields, replacements, cancellations, instructions, statuses and opaque confirmations. Unlinked/stale replacements quarantine; instruction cancellation never cancels the event. Omitted replacement fields retain original provenance with review required. Complex option renumbering, semantic MT568 supersession, out-of-order recovery and complete sender-specific account identity remain unsupported; do not treat the ledger as an authoritative custody system.\n\nNo automatic LLM disagreement experiment was possible because no local LLM was configured. This is unmeasured, not assumed helpful. DisabledFallback returns UNKNOWN without external calls.\n\n'
    m+='## 16. Did structure improve end-to-end performance?\n\n**Not established.** Deterministic extraction works on the explicitly scoped generated fixtures, but zero existing public rows have ISO fields, one official partial excerpt is insufficient, and no independently expert-labelled structured event test exists. Narrow training learns the synthetic three-target task but transfers inconsistently. This PoC is suitable for an honestly labelled research demonstration, not a customer quality/automation claim. The quality gate remains NOT MET.\n\nDiagnostic confidence coverage on known synthetic validation (three predicates, not complete event decisions):\n\n| Threshold | Fine coverage | Three-predicate exact agreement | Wrong selected |\n|---|---:|---:|---:|\n'
    for r in coverage['fine']:m+=f"| {r['threshold']:.2f} | {r['coverage']:.1%} | {r['exact_three_predicate_accuracy']:.1%} | {r['errors']} |\n" if r['exact_three_predicate_accuracy'] is not None else f"| {r['threshold']:.2f} | {r['coverage']:.1%} | unmeasured | {r['errors']} |\n"
    m+='\nNo threshold is approved for automation: these labels are synthetic, duplicates cross the supplied splits, validation is not independent test evidence, all predicates lack sufficient verified support, and challenge errors remain. Latencies are persisted per source in JSONL, but runs were not isolated hardware benchmarks (training/other activity overlapped); do not infer a fair throughput win. A new narrow learning curve was not run; the earlier whole-text head-only curve is a different experiment and is not reused as evidence of narrow-task sample efficiency.\n\n## 17. Highest-value next experiment\n\nObtain a permissioned, sender-profile-specific set of genuine linked meeting notifications/narratives with expert-labelled voting eligibility and all seven predicates. Freeze a duplicate/event-grouped independent test before any tuning. Evaluate deterministic parsing and whole-text versus passage-based narrow Laya on exactly those events, with a validation-only aggregation ablation. This simultaneously addresses corpus validity, missing supervision and the inability of the current unstructured challenge to test structural benefit.\n\n## Reproduction and verification\n\nSee README for commands. Historical frozen study hashes are unchanged. Native probability validity, source-exact evidence, fixture provenance, full public-row counts, SQLite event history persistence and checkpoint reload are checked. Both new checkpoints reload identically on a fixed first-case prediction sequence; this is a narrower check than the previous study’s all-100 reload verification. Application and browser test logs are separate from deliberately failing real-model semantic checks. Automation remains disabled throughout.\n'
    Path('data/reports/ISO15022_HYBRID_EVALUATION.md').write_text(m)
    # Plots describe observed diagnostics only.
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    loss=json.loads(Path('data/experiments/narrow-v1/training-result.json').read_text())['training']['epoch_loss']
    fig,ax=plt.subplots(figsize=(6,3));ax.plot(range(1,5),loss,marker='o');ax.set(xlabel='Epoch',ylabel='Training loss',title='Narrow synthetic training loss (not generalisation)');fig.tight_layout();fig.savefig(OUT/'narrow-training-loss.png');plt.close(fig)
    print({k:v['passed'] for k,v in comparison.items()})
if __name__=='__main__':report()
